import type { HTMLAttributes, ReactNode } from 'react'
import { Check, Minus, X } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ComparisonValue = ReactNode | boolean | null
export type ComparisonColumn = { key: string; label: string; highlighted?: boolean }
export type ComparisonRow = { label: string; values: Record<string, ComparisonValue> }

export interface ComparisonTableProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  caption: string
  description?: string
  columns: readonly ComparisonColumn[]
  rows: readonly ComparisonRow[]
  firstColumnLabel?: string
  emptyMessage?: string
}

function Value({ value }: { value: ComparisonValue }) {
  if (value === true)
    return <Check className="mx-auto h-5 w-5 text-emerald-600" aria-label="Incluído" />
  if (value === false)
    return <X className="mx-auto h-5 w-5 text-muted-foreground" aria-label="Não incluído" />
  if (value == null)
    return <Minus className="mx-auto h-5 w-5 text-muted-foreground" aria-label="Não informado" />
  return <>{value}</>
}

export function ComparisonTable({
  caption,
  description,
  columns,
  rows,
  firstColumnLabel = 'Recurso',
  emptyMessage = 'Nenhum item para comparar.',
  className,
  ...props
}: ComparisonTableProps) {
  return (
    <section className={cn('w-full', className)} {...props}>
      <div className="mb-6">
        <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{caption}</h2>
        {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      </div>
      {!columns.length || !rows.length ? (
        <p className="rounded-2xl border border-dashed p-8 text-center text-muted-foreground">
          {emptyMessage}
        </p>
      ) : (
        <div className="overflow-x-auto rounded-2xl border">
          <table className="w-full min-w-[40rem] border-collapse text-left text-sm">
            <caption className="sr-only">{caption}</caption>
            <thead className="bg-muted/60">
              <tr>
                <th scope="col" className="p-4 font-semibold">
                  {firstColumnLabel}
                </th>
                {columns.map((column) => (
                  <th
                    key={column.key}
                    scope="col"
                    className={cn(
                      'p-4 text-center font-semibold',
                      column.highlighted && 'bg-primary/10 text-primary',
                    )}
                  >
                    {column.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.label} className="border-t transition-colors hover:bg-muted/30">
                  <th scope="row" className="p-4 font-medium">
                    {row.label}
                  </th>
                  {columns.map((column) => (
                    <td
                      key={column.key}
                      className={cn(
                        'p-4 text-center text-muted-foreground',
                        column.highlighted && 'bg-primary/5',
                      )}
                    >
                      <Value value={row.values[column.key]} />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { cn } from '@/lib/utils'

export type FeatureGridProps = {
  title?: string
  description?: string
  features: Array<{ title: string; description: string; icon?: LucideIcon }>
  className?: string
}

export function FeatureGrid({ title, description, features, className }: FeatureGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'features-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="features-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? (
          <p className="mt-4 max-w-2xl text-lg text-muted-foreground">{description}</p>
        ) : null}
        <div
          className={cn(
            'mt-10 grid gap-5 md:grid-cols-2',
            features.length % 4 === 0 ? 'lg:grid-cols-4' : 'lg:grid-cols-3',
          )}
        >
          {features.map(({ title: featureTitle, description: featureDescription, icon: Icon }) => (
            <article
              key={featureTitle}
              className="rounded-2xl border bg-card p-6 text-card-foreground shadow-sm transition hover:-translate-y-1 hover:shadow-md"
            >
              {Icon ? (
                <span className="mb-5 flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 text-primary">
                  <Icon className="h-5 w-5" aria-hidden="true" />
                </span>
              ) : null}
              <h3 className="text-lg font-semibold">{featureTitle}</h3>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">{featureDescription}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import Link from 'next/link'
import { ArrowRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type CTAInlineProps = {
  title: string
  description?: string
  action: { label: string; href: string }
  className?: string
}

export function CTAInline({ title, description, action, className }: CTAInlineProps) {
  return (
    <aside
      className={cn(
        'flex flex-col gap-5 rounded-2xl border bg-muted/30 p-6 sm:flex-row sm:items-center sm:justify-between md:p-8',
        className,
      )}
      aria-label={title}
    >
      <div>
        <h2 className="text-xl font-semibold">{title}</h2>
        {description ? <p className="mt-1 text-sm text-muted-foreground">{description}</p> : null}
      </div>
      <Button asChild className="shrink-0">
        <Link href={action.href}>
          {action.label}
          <ArrowRight className="ml-2 h-4 w-4" aria-hidden="true" />
        </Link>
      </Button>
    </aside>
  )
}

'use client'

import { useId, useMemo, useState } from 'react'
import { Search, X } from 'lucide-react'

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export type FAQSearchItem = {
  question: string
  answer: React.ReactNode
  searchText?: string
  category?: string
}

export type FAQSearchProps = {
  title: string
  description?: string
  items: FAQSearchItem[]
  placeholder?: string
  emptyMessage?: string
  className?: string
}

export function FAQSearch({
  title,
  description,
  items,
  placeholder = 'Busque por uma dúvida...',
  emptyMessage = 'Nenhuma resposta encontrada. Tente buscar por outros termos.',
  className,
}: FAQSearchProps) {
  const titleId = useId()
  const searchId = useId()
  const [query, setQuery] = useState('')

  const filteredItems = useMemo(() => {
    const normalizedQuery = query.trim().toLocaleLowerCase()
    if (!normalizedQuery) return items

    return items.filter((item) =>
      [item.question, item.searchText, item.category]
        .filter(Boolean)
        .join(' ')
        .toLocaleLowerCase()
        .includes(normalizedQuery),
    )
  }, [items, query])

  return (
    <section className={cn('bg-muted/40 py-16 md:py-24', className)} aria-labelledby={titleId}>
      <div className="container max-w-4xl">
        <header className="mb-8">
          <h2 id={titleId} className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
          {description ? (
            <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p>
          ) : null}
        </header>

        <div className="relative mb-8">
          <label htmlFor={searchId} className="sr-only">
            Pesquisar nas perguntas frequentes
          </label>
          <Search
            className="pointer-events-none absolute left-4 top-1/2 size-5 -translate-y-1/2 text-muted-foreground"
            aria-hidden="true"
          />
          <Input
            id={searchId}
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={placeholder}
            className="h-14 rounded-2xl bg-background pl-12 pr-12 text-base shadow-sm"
          />
          {query ? (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              onClick={() => setQuery('')}
              className="absolute right-2 top-1/2 -translate-y-1/2 rounded-full"
              aria-label="Limpar pesquisa"
            >
              <X className="size-4" />
            </Button>
          ) : null}
        </div>

        <p className="sr-only" aria-live="polite">
          {filteredItems.length} perguntas encontradas
        </p>

        {filteredItems.length ? (
          <Accordion type="single" collapsible className="rounded-2xl border bg-background px-5">
            {filteredItems.map((item, index) => (
              <AccordionItem key={item.question} value={`faq-search-${index}`}>
                <AccordionTrigger className="gap-4 py-5 text-left hover:no-underline">
                  <span>
                    {item.category ? (
                      <span className="mb-1 block text-xs font-semibold uppercase tracking-wider text-primary">
                        {item.category}
                      </span>
                    ) : null}
                    {item.question}
                  </span>
                </AccordionTrigger>
                <AccordionContent className="max-w-3xl pb-5 leading-7 text-muted-foreground">
                  {item.answer}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        ) : (
          <div className="rounded-2xl border border-dashed bg-background px-6 py-12 text-center text-sm text-muted-foreground">
            {emptyMessage}
          </div>
        )}
      </div>
    </section>
  )
}

import { Quote, Star } from 'lucide-react'

import { cn } from '@/lib/utils'

export type SpotlightTestimonial = {
  quote: string
  name: string
  role?: string
  company?: string
  avatar?: { src: string; alt: string }
  rating?: number
}

export type TestimonialsSpotlightProps = {
  eyebrow?: string
  title?: string
  featured: SpotlightTestimonial
  items?: SpotlightTestimonial[]
  className?: string
}

function Author({ item }: { item: SpotlightTestimonial }) {
  return (
    <div className="flex items-center gap-3">
      {item.avatar ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={item.avatar.src}
          alt={item.avatar.alt}
          className="size-11 rounded-full object-cover"
        />
      ) : (
        <span className="flex size-11 items-center justify-center rounded-full bg-primary/10 font-semibold text-primary">
          {item.name.charAt(0)}
        </span>
      )}
      <div>
        <p className="font-semibold">{item.name}</p>
        {(item.role || item.company) && (
          <p className="text-sm text-muted-foreground">
            {[item.role, item.company].filter(Boolean).join(' · ')}
          </p>
        )}
      </div>
    </div>
  )
}

export function TestimonialsSpotlight({
  eyebrow = 'Histórias de clientes',
  title = 'Confiança construída em cada entrega.',
  featured,
  items = [],
  className,
}: TestimonialsSpotlightProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <header className="mb-10 max-w-2xl">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
            {eyebrow}
          </p>
          <h2 className="mt-3 text-balance text-3xl font-bold tracking-tight md:text-5xl">
            {title}
          </h2>
        </header>

        <div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]">
          <article className="relative overflow-hidden rounded-3xl bg-foreground p-7 text-background md:p-10">
            <Quote className="absolute right-6 top-6 size-20 opacity-10" aria-hidden="true" />
            <div className="mb-8 flex gap-1" aria-label={`${featured.rating ?? 5} de 5 estrelas`}>
              {Array.from({ length: featured.rating ?? 5 }, (_, index) => (
                <Star key={index} className="size-4 fill-current text-amber-400" />
              ))}
            </div>
            <blockquote className="max-w-3xl text-balance text-2xl font-medium leading-relaxed md:text-3xl">
              “{featured.quote}”
            </blockquote>
            <div className="mt-10 [&_*]:text-inherit">
              <Author item={featured} />
            </div>
          </article>

          <div className="grid gap-5">
            {items.slice(0, 2).map((item) => (
              <article
                key={`${item.name}-${item.quote}`}
                className="rounded-3xl border bg-card p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-lg motion-reduce:transform-none"
              >
                <blockquote className="mb-6 leading-7 text-muted-foreground">
                  “{item.quote}”
                </blockquote>
                <Author item={item} />
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'
import Image from 'next/image'

import { HoverButton } from '@/components/library/primitives/HoverButton'
import { cn } from '@/lib/utils'

export type BannerImmersiveProps = {
  image: { src: string; alt: string }
  title: string
  eyebrow?: string
  symbol?: ReactNode
  description?: string
  actions?: readonly { label: string; href: string; variant?: 'primary' | 'light' | 'outline' }[]
  align?: 'left' | 'center'
  height?: 'screen' | 'large'
  overlay?: 'light' | 'medium' | 'strong'
  className?: string
}

const overlays = {
  light: 'bg-black/25',
  medium: 'bg-black/45',
  strong: 'bg-black/65',
}

/** Banner fotográfico de tela cheia — sem navbar; combine com um componente de Navbars. */
export function BannerImmersive({
  image,
  title,
  eyebrow,
  symbol,
  description,
  actions = [],
  align = 'center',
  height = 'large',
  overlay = 'medium',
  className,
}: BannerImmersiveProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-slate-950 text-white',
        height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
        className,
      )}
      aria-labelledby="banner-immersive-title"
    >
      <Image src={image.src} alt={image.alt} fill priority className="object-cover" sizes="100vw" />
      <div className={cn('absolute inset-0', overlays[overlay])} />
      <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-black/60 to-transparent" />

      <div
        className={cn(
          'container relative z-10 flex items-center py-20',
          height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
          align === 'center' ? 'justify-center text-center' : 'justify-start text-left',
        )}
      >
        <div className={cn('max-w-4xl', align === 'center' && 'flex flex-col items-center')}>
          {symbol ? <div className="mb-6 text-white">{symbol}</div> : null}
          {eyebrow ? (
            <p className="mb-4 text-xs font-bold uppercase tracking-[0.25em] text-white/70">
              {eyebrow}
            </p>
          ) : null}
          <h1
            id="banner-immersive-title"
            className="text-5xl font-bold tracking-tight sm:text-6xl lg:text-8xl"
          >
            {title}
          </h1>
          {description ? (
            <p className="mt-6 max-w-2xl text-base leading-8 text-white/75 sm:text-lg">
              {description}
            </p>
          ) : null}
          {actions.length ? (
            <div className="mt-9 flex flex-wrap gap-3">
              {actions.map((action) => (
                <HoverButton
                  key={`${action.label}-${action.href}`}
                  href={action.href}
                  effect={action.variant === 'outline' ? 'glow' : 'lift'}
                  variant={action.variant === 'primary' ? 'default' : 'secondary'}
                  size="lg"
                  className={cn(
                    'rounded-full',
                    action.variant === 'outline' &&
                      'border border-white/40 bg-transparent text-white hover:bg-white/10',
                  )}
                >
                  {action.label}
                </HoverButton>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
      src={BLOOMIN_LOGO_SRC}
      alt="Bloomin"
      width={Math.round(height * (421 / 108))}
      height={height}
      className={cn('h-[1.125rem] w-auto', className)}
      style={{ height, width: 'auto' }}
    />
  )
}

export type BloominCreditProps = {
  label?: string
  href?: string
  className?: string
  /** Fundo escuro atrás do logo (o PNG oficial tem fundo preto). */
  logoClassName?: string
}

/** Crédito padrão “Desenvolvido por” com o logo da Bloomin. */
export function BloominCredit({
  label = 'Desenvolvido por',
  href = BLOOMIN_URL,
  className,
  logoClassName,
}: BloominCreditProps) {
  return (
    <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
      <span className="opacity-80">{label}</span>
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Bloomin — agência de marketing digital"
        className={cn(
          'inline-flex items-center rounded-md bg-neutral-950 px-2 py-1 transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          logoClassName,
        )}
      >
        <BloominLogo height={16} />
      </a>
    </span>
  )
}

import * as React from 'react'

import { CurrentYear } from '@/components/library/primitives/CurrentYear'
import { cn } from '@/lib/utils'

import { BloominCredit } from './BloominCredit'
import type { NavigationBrand, NavigationLink, SocialLink } from './types'

export interface FooterCompactProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  brand: NavigationBrand
  links?: readonly NavigationLink[]
  socialLinks?: readonly SocialLink[]
  copyright?: React.ReactNode
  navigationLabel?: string
  /** Exibe “Desenvolvido por” com o logo da Bloomin. Padrão: true. */
  showDevelopedBy?: boolean
}

export function FooterCompact({
  brand,
  links = [],
  socialLinks = [],
  copyright,
  navigationLabel = 'Navegação do rodapé',
  showDevelopedBy = true,
  className,
  ...props
}: FooterCompactProps) {
  return (
    <footer className={cn('border-t bg-background', className)} {...props}>
      <div className="mx-auto flex max-w-7xl flex-col items-center gap-6 px-4 py-8 sm:px-6 lg:flex-row lg:px-8">
        <a
          href={brand.href ?? '/'}
          className="inline-flex items-center gap-3 rounded-sm font-semibold tracking-tight focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {brand.logo}
          <span>{brand.label}</span>
        </a>

        {links.length ? (
          <nav className="lg:ml-auto" aria-label={navigationLabel}>
            <ul className="flex flex-wrap justify-center gap-x-5 gap-y-2">
              {links.map((link) => (
                <li key={link.href}>
                  <a
                    href={link.href}
                    target={link.external ? '_blank' : undefined}
                    rel={link.external ? 'noopener noreferrer' : undefined}
                    aria-current={link.current ? 'page' : undefined}
                    className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
        ) : null}

        {socialLinks.length ? (
          <ul className="flex items-center gap-2" aria-label="Redes sociais">
            {socialLinks.map((link) => (
              <li key={link.href}>
                <a
                  href={link.href}
                  aria-label={link.label}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex h-9 w-9 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {link.icon}
                </a>
              </li>
            ))}
          </ul>
        ) : null}
      </div>

      <div className="border-t">
        <div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-3 px-4 py-4 text-xs text-muted-foreground sm:flex-row sm:px-6 lg:px-8">
          <div className="text-center sm:text-left">
            {copyright ?? (
              <>
                © <CurrentYear /> {brand.label}
              </>
            )}
          </div>
          {showDevelopedBy ? <BloominCredit className="text-xs" /> : null}
        </div>
      </div>
    </footer>
  )
}

'use client'

import * as React from 'react'
import { Menu } from 'lucide-react'

import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

import type { NavigationAction, NavigationBrand, NavigationItem } from './types'

export interface MobileDrawerProps {
  brand: NavigationBrand
  items: readonly NavigationItem[]
  actions?: readonly NavigationAction[]
  trigger?: React.ReactNode
  triggerLabel?: string
  navigationLabel?: string
  className?: string
}

function ExternalAttributes({ external }: { external?: boolean }) {
  return external ? { target: '_blank', rel: 'noopener noreferrer' } : {}
}

export function MobileDrawer({
  brand,
  items,
  actions = [],
  trigger,
  triggerLabel = 'Abrir menu',
  navigationLabel = 'Navegação móvel',
  className,
}: MobileDrawerProps) {
  return (
    <Dialog>
      <DialogTrigger asChild>
        {trigger ?? (
          <Button variant="ghost" size="icon" aria-label={triggerLabel}>
            <Menu className="h-5 w-5" aria-hidden="true" />
          </Button>
        )}
      </DialogTrigger>
      <DialogContent
        className={cn(
          'bottom-0 left-auto right-0 top-0 flex h-dvh w-[min(24rem,90vw)] max-w-none translate-x-0 translate-y-0 flex-col rounded-none p-0 data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right',
          className,
        )}
      >
        <div className="border-b px-6 py-5 pr-14">
          <DialogTitle className="text-left">
            <a href={brand.href ?? '/'} className="inline-flex items-center gap-3">
              {brand.logo}
              <span>{brand.label}</span>
            </a>
          </DialogTitle>
          <DialogDescription className="sr-only">{navigationLabel}</DialogDescription>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-5" aria-label={navigationLabel}>
          <ul className="space-y-1">
            {items.map((item) => (
              <li key={item.href}>
                <DialogClose asChild>
                  <a
                    href={item.href}
                    aria-current={item.current ? 'page' : undefined}
                    className={cn(
                      'flex min-h-11 items-center gap-3 rounded-md px-3 py-2 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      item.current && 'bg-muted text-primary',
                    )}
                    {...ExternalAttributes(item)}
                  >
                    {item.icon}
                    {item.label}
                  </a>
                </DialogClose>
                {item.children?.length ? (
                  <ul className="mb-2 ml-5 border-l pl-3">
                    {item.children.map((child) => (
                      <li key={child.href}>
                        <DialogClose asChild>
                          <a
                            href={child.href}
                            aria-current={child.current ? 'page' : undefined}
                            className="block rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                            {...ExternalAttributes(child)}
                          >
                            {child.label}
                          </a>
                        </DialogClose>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ul>
        </nav>

        {actions.length ? (
          <div className="grid gap-2 border-t p-4">
            {actions.map((action) => (
              <Button key={action.href} asChild variant={action.variant}>
                <a href={action.href} {...ExternalAttributes(action)}>
                  {action.label}
                </a>
              </Button>
            ))}
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

